function model(p) {
  // One illustrative B2B deal moving from lead to cash. Stage days are typical illustrative values, not benchmarks.
  // Event times are playback seconds for the explainer; days are the deal's calendar days.
  const disc = Math.max(0, Math.min(30, Math.round(p.discount / 5) * 5));
  const hold = Math.round(p.credit) === 1;
  const LIMIT = 15, LIST = 120000;
  const net = Math.round(LIST * (1 - disc / 100));
  const needApproval = disc > LIMIT;
  const approvalDays = needApproval ? 2 + (disc - LIMIT) / 5 * 2 : 0;
  const money = v => '$' + v.toLocaleString('en-US');
  const DEF = [
    ['lead', 'Lead', 2, 'Marketing captures the lead and routes it to a sales rep within service-level targets.'],
    ['qualify', 'Qualify', 7, 'Discovery confirms budget, decision maker, need and timeline before the rep invests in a quote.'],
    ['quote', 'Quote', 3, 'Configure, price, quote: products, list price and any discount, assembled into a quote document.'],
    ['approval', 'Discount approval', approvalDays, 'Discounts above ' + LIMIT + '% need a sales manager\'s approval. Deeper discounts take longer to justify.'],
    ['contract', 'Contract', 10, 'Legal redlines and signatures. The signed contract fixes the price, terms and start date.'],
    ['credit', 'Credit check', 1, 'Finance checks the customer\'s credit limit and payment history before booking the order.'],
    ['hold', 'Credit hold', 9, 'An over-limit customer stalls here until finance gets a deposit or raises the limit.'],
    ['order', 'Order', 2, 'The order is booked in the order system and provisioning or shipping starts.'],
    ['invoice', 'Invoice', 1, 'Billing issues the invoice with net 30 payment terms.'],
    ['payment', 'Payment', 30, 'The customer pays within its terms and the cash is applied to the invoice: the deal is closed and paid.']
  ];
  const stations = DEF.map(([id, label, days, detail], k) => ({
    id, k, label, detail, days, onPath: id === 'approval' ? needApproval : id === 'hold' ? hold : true
  }));
  const raw = [];
  const add = (station, kind, days, note) => raw.push({ station, kind, days, note, dur: days ? 1.3 + 0.03 * days : 0.9 });
  add('lead', 'lead', 2, 'An inbound lead from a mid-size manufacturer is routed to a sales rep.');
  add('qualify', 'qualify', 7, 'Discovery confirms budget, decision maker, need and timeline.');
  add('quote', 'quote', 3, 'Quote: ' + money(LIST) + ' a year at list, ' + disc + '% discount, ' + money(net) + ' net.');
  if (needApproval) {
    add('approval', 'wait', approvalDays, disc + '% is above the ' + LIMIT + '% limit: the deal waits ' + approvalDays + ' days for a manager.');
    add('approval', 'approved', 0, 'The sales manager approves the discount and the quote goes to the customer.');
  }
  add('contract', 'contract', 10, 'Redlines and signatures take 10 days; the signed contract locks the price.');
  add('credit', hold ? 'over' : 'pass', 1, hold ? 'Credit check: the customer is over its credit limit.' : 'Credit check: within the limit, so the order can be booked.');
  if (hold) {
    add('hold', 'wait', 9, 'Credit hold: the deal stalls 9 days until the customer pays a deposit.');
    add('hold', 'released', 0, 'The deposit arrives and finance releases the hold.');
  }
  add('order', 'order', 2, 'The order is booked and provisioning starts.');
  add('invoice', 'invoice', 1, 'The invoice for ' + money(net) + ' goes out with net 30 terms.');
  add('payment', 'paid', 30, 'Cash arrives and is applied to the invoice: closed and paid.');
  const total = raw.reduce((a, e) => a + e.dur, 0), scale = Math.min(14 / total, Math.max(1, 7 / total));
  let t = 0, day = 0;
  const events = raw.map((e, i) => {
    const ev = Object.assign({ i, start: +t.toFixed(2), dayStart: day, dayEnd: day + e.days }, e, { dur: +(e.dur * scale).toFixed(2) });
    t += e.dur * scale; day += e.days; return ev;
  });
  const stallDays = approvalDays + (hold ? 9 : 0);
  const stalls = [];
  if (needApproval) stalls.push(approvalDays + ' days waiting for discount approval');
  if (hold) stalls.push('9 days on credit hold');
  const summary = 'Paid on day ' + day + (stallDays
    ? ', ' + stallDays + ' of them stalled: ' + stalls.join(' and ') + '.'
    : ' with no stalls: a ' + disc + '% discount needs no approval and credit passed.');
  return {
    stations, events, duration: +t.toFixed(2), markers: events.map(e => e.start),
    discountPct: disc, approvalLimit: LIMIT, approvalStep: needApproval, approvalDays, creditHold: hold,
    listValue: LIST, netValue: net, totalDays: day, stallDays, summary
  };
}

checkCode:
function check(p) {
  const m = model(p), ev = m.events, order = m.stations.map(s => s.id);
  const disc = Math.round(p.discount / 5) * 5, hold = Math.round(p.credit) === 1;
  const has = id => ev.some(e => e.station === id);
  const approvalOk = has('approval') === (disc > 15);
  const holdOk = has('hold') === hold;
  const idx = ev.map(e => order.indexOf(e.station));
  const ordered = idx.every((k, i) => k >= 0 && (i === 0 || (k >= idx[i - 1] && ev[i].start > ev[i - 1].start)));
  const required = ['lead', 'qualify', 'quote', 'contract', 'credit', 'order', 'invoice', 'payment'].every(has);
  const ends = ev[0].station === 'lead' && ev[ev.length - 1].station === 'payment';
  const pathDays = m.stations.filter(s => s.onPath).reduce((a, s) => a + s.days, 0);
  const daysOk = ev.reduce((a, e) => a + e.days, 0) === m.totalDays && pathDays === m.totalDays;
  return {
    pass: approvalOk && holdOk && ordered && required && ends && daysOk,
    detail: 'Discount ' + disc + '% ' + (disc > 15 ? '> 15%, so an approval step (' + m.approvalDays + ' days)' : '<= 15%, so no approval step') +
      '; credit ' + (hold ? 'Hold, so a 9-day hold' : 'Pass, so no hold') + '; ' + new Set(ev.map(e => e.station)).size +
      ' stages in valid order from lead to payment, paid on day ' + m.totalDays + ' (' + m.stallDays + ' days stalled).'
  };
}
